/// Every location of a one-symbol response, without its `symbol` field (the
/// tool renders the canonical name there, whichever spelling was asked).
fn locations_of(response: &Value) -> Vec<Value> {
    response["locations"]
        .as_array()
        .map(|locations| {
            locations
                .iter()
                .map(|location| {
                    let mut location = location.clone();
                    if let Some(object) = location.as_object_mut() {
                        object.remove("symbol");
                    }
                    location
                })
                .collect()
        })
        .unwrap_or_default()
}

/// The sheet says "on the P1 fixture", but `Top::Only` / `Top$Only` name the
/// one-level fixture (`struct Top { struct Only { int b; }; };`), which is
/// what this probe uses.
#[test]
fn judge_3631_p10_mcp_get_symbol_locations_parity() {
    let project = InlineTestProject::with_language(Language::Cpp)
        .file("nested.cpp", "struct Top { struct Only { int b; }; };\n")
        .build();
    let colon = call_tool(&project, "get_symbol_locations", r#"{"symbols":["Top::Only"]}"#);
    let dollar = call_tool(&project, "get_symbol_locations", r#"{"symbols":["Top$Only"]}"#);
    let missing = call_tool(&project, "get_symbol_locations", r#"{"symbols":["Top::Missing"]}"#);
    let colon_locations = locations_of(&colon);
    let dollar_locations = locations_of(&dollar);
    let missing_locations = locations_of(&missing);
    println!(
        "JUDGE3631 OBS case=p10 colon={} dollar={} missing={}",
        colon.to_string(),
        dollar.to_string(),
        missing.to_string()
    );
    assert_eq!(colon_locations.len(), 1, "p10: one location for Top::Only: {colon}");
    assert_eq!(
        colon_locations, dollar_locations,
        "p10: Top::Only reports the same file and lines as Top$Only"
    );
    assert!(missing_locations.is_empty(), "p10: no location for Top::Missing: {missing}");
}
